@Transactional(isolation = Isolation.REPEATABLE_READ)
public void processAccountTransfer(Long fromId, Long toId, BigDecimal amount) {
    // In REPEATABLE_READ, the balance read here remains constant for the duration of the method
    Account from = accountRepository.findById(fromId);
    if (from.getBalance().compareTo(amount) >= 0) {
        accountRepository.decrementBalance(fromId, amount);
        accountRepository.incrementBalance(toId, amount);
    }
}
